class Solution {
    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums1.length == 0 || nums2.length == 0 || k <= 0) {
            return result;
        }

        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> compare(a, b, nums1, nums2));
        Set<Long> seen = new HashSet<>();
        offer(heap, seen, 0, 0, nums1.length, nums2.length);

        while (!heap.isEmpty() && result.size() < k) {
            int[] cell = heap.poll();
            int i = cell[0];
            int j = cell[1];
            result.add(Arrays.asList(nums1[i], nums2[j]));
            offer(heap, seen, i + 1, j, nums1.length, nums2.length);
            offer(heap, seen, i, j + 1, nums1.length, nums2.length);
        }
        return result;
    }

    private void offer(PriorityQueue<int[]> heap, Set<Long> seen, int i, int j, int m, int n) {
        if (i >= m || j >= n) {
            return;
        }
        long key = (((long) i) << 32) ^ (j & 0xffffffffL);
        if (seen.add(key)) {
            heap.offer(new int[]{i, j});
        }
    }

    private int compare(int[] a, int[] b, int[] nums1, int[] nums2) {
        long sumA = (long) nums1[a[0]] + nums2[a[1]];
        long sumB = (long) nums1[b[0]] + nums2[b[1]];
        int bySum = Long.compare(sumA, sumB);
        if (bySum != 0) {
            return bySum;
        }
        int byFirst = Integer.compare(nums1[a[0]], nums1[b[0]]);
        if (byFirst != 0) {
            return byFirst;
        }
        int bySecond = Integer.compare(nums2[a[1]], nums2[b[1]]);
