class Solution {
    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        List<int[]> candidates = new ArrayList<>();
        int limit1 = Math.min(nums1.length, k);
        int limit2 = Math.min(nums2.length, k);
        for (int i = 0; i < limit1; i++) {
            for (int j = 0; j < limit2; j++) {
                candidates.add(new int[]{i, j});
            }
        }

        candidates.sort((a, b) -> compare(a, b, nums1, nums2));

        List<List<Integer>> result = new ArrayList<>();
        int limit = Math.min(k, candidates.size());
        for (int index = 0; index < limit; index++) {
            int[] cell = candidates.get(index);
            result.add(Arrays.asList(nums1[cell[0]], nums2[cell[1]]));
        }
        return result;
    }

    private int compare(int[] a, int[] b, int[] nums1, int[] nums2) {
        long sumA = (long) nums1[a[0]] + nums2[a[1]];
        long sumB = (long) nums1[b[0]] + nums2[b[1]];
        int bySum = Long.compare(sumA, sumB);
