import java.util.*;

class Solution {
    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums1.length == 0 || nums2.length == 0 || k <= 0) {
            return result;
        }

        int target = (int) Math.min((long) k, (long) nums1.length * nums2.length);
        long low = (long) nums1[0] + nums2[0];
        long high = (long) nums1[nums1.length - 1] + nums2[nums2.length - 1];
        while (low < high) {
            long mid = low + (high - low) / 2;
            if (countAtMost(nums1, nums2, mid, target) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        long threshold = low;
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> compare(a, b, nums1, nums2));
        for (int i = 0; i < nums1.length && i < target; i++) {
            if ((long) nums1[i] + nums2[0] > threshold) {
                break;
            }
            heap.offer(new int[]{i, 0});
        }

        while (!heap.isEmpty() && result.size() < target) {
            int[] cell = heap.poll();
            int i = cell[0];
            int j = cell[1];
            if ((long) nums1[i] + nums2[j] > threshold) {
                break;
            }
            result.add(Arrays.asList(nums1[i], nums2[j]));
            if (j + 1 < nums2.length && (long) nums1[i] + nums2[j + 1] <= threshold) {
                heap.offer(new int[]{i, j + 1});
            }
        }
        return result;
    }

    private long countAtMost(int[] nums1, int[] nums2, long limit, int stopAt) {
        long count = 0;
        int j = nums2.length - 1;
        for (int value : nums1) {
            while (j >= 0 && (long) value + nums2[j] > limit) {
                j--;
            }
            count += j + 1L;
            if (count >= stopAt) {
                return count;
            }
        }
        return count;
    }

    private int compare(int[] a, int[] b, int[] nums1, int[] nums2) {
        long sumA = (long) nums1[a[0]] + nums2[a[1]];
        long sumB = (long) nums1[b[0]] + nums2[b[1]];
        int bySum = Long.compare(sumA, sumB);
        if (bySum != 0) {
            return bySum;
        }
        int byFirst = Integer.compare(nums1[a[0]], nums1[b[0]]);
        if (byFirst != 0) {
            return byFirst;
        }
        int bySecond = Integer.compare(nums2[a[1]], nums2[b[1]]);
        if (bySecond != 0) {
            return bySecond;
        }
        int byRow = Integer.compare(a[0], b[0]);
        if (byRow != 0) {
            return byRow;
        }
        return Integer.compare(a[1], b[1]);
    }
}
